// ============================================================================
// Write the food-item and recipe migrations from the repo's editorial sources
//
//   node --import ./scripts/testAlias.mjs scripts/buildRecipes.mjs [--check]
//
// Sources: src/lib/food/foodData.js (generated by scripts/foodsResolve.py from
// IFCT 2017 and the cited references in scripts/foods.source.json) and
// src/lib/food/recipes/*.js (editorial). Until the food database is edited from
// the staff tools these files are the source of truth, and the database mirrors
// them: 00087 creates and fills food.food_item, 00088 adds amounts and a method
// to every dish. --check fails when a migration is stale. Both are idempotent.
// ============================================================================

import fs from "node:fs";
import path from "node:path";
import { FOODS, FOOD_VERSION } from "@/lib/food/foodData";
import { DISHES } from "@/lib/food/dishData";
import { RECIPES } from "@/lib/food/recipes/index";
import { createHash } from "node:crypto";

const CHECK = process.argv.includes("--check");
const DIR = path.resolve(process.cwd(), "..", "supabase", "migrations");
const q = (s) => (s === null || s === undefined ? "NULL" : `'${String(s).replace(/'/g, "''")}'`);
const n = (x) => (x === null || x === undefined ? "NULL" : String(x));
const RECIPE_VERSION = createHash("sha256").update(JSON.stringify(RECIPES)).digest("hex").slice(0, 12);

const foodRows = FOODS.map((f) => `  (${[
  q(f.key), q(f.name), n(f.per100.kcal), n(f.per100.protein), n(f.per100.carbs), n(f.per100.fat), n(f.per100.fibre ?? 0),
  q(f.source), q(f.sourceRef), n(f.fridgeDays ?? null), n(f.cookedYield ?? null),
  `${q(JSON.stringify(f.measures ?? {}))}::jsonb`, q(f.pieceName ?? null), f.pieceIsName ? "true" : "false", q(FOOD_VERSION),
].join(", ")})`).join(",\n");

const foods = `-- ============================================================================
-- 00087_food_items — what a recipe line IS, per 100 g (exact macros, P1).
-- GENERATED by web/scripts/buildRecipes.mjs. Do not edit; regenerate.
--
-- The ingredient graph says what a line CONTAINS ("Milk" is curd, paneer and
-- cream alike). A food item says what it is, for sizing a portion: per-100 g
-- figures for the raw, edible food. Most rows are IFCT 2017 (ICMR-NIN), with
-- the IFCT food code in source_ref; the rest say where they come from:
-- usda_fdc (USDA FoodData Central), icmr_nvif_1989 (Nutritive Value of Indian
-- Foods), or koi_estimate (a typical label). A KOI shelf line is sized with the
-- product's own label first; a food item is the fallback, and the only source
-- for fresh and kitchen lines. IFCT energy is kJ / 4.184; carbs are available
-- carbohydrate, fibre separate. measures: grams per cup / tbsp / tsp / piece.
-- This is the seed of KOI's food database: rows carry a data_version.
-- ============================================================================

CREATE TABLE IF NOT EXISTS food.food_item (
  key           text PRIMARY KEY CHECK (key ~ '^[a-z0-9_]+$'),
  name          text NOT NULL CHECK (btrim(name) <> ''),
  kcal_100g     numeric(6,1) NOT NULL CHECK (kcal_100g >= 0),
  protein_100g  numeric(6,2) NOT NULL CHECK (protein_100g >= 0),
  carbs_100g    numeric(6,2) NOT NULL CHECK (carbs_100g >= 0),
  fat_100g      numeric(6,2) NOT NULL CHECK (fat_100g >= 0),
  fibre_100g    numeric(6,2) NOT NULL DEFAULT 0 CHECK (fibre_100g >= 0),
  source        text NOT NULL CHECK (source IN ('ifct_2017', 'usda_fdc', 'icmr_nvif_1989', 'koi_estimate')),
  source_ref    text NOT NULL CHECK (btrim(source_ref) <> ''),
  fridge_days   smallint CHECK (fridge_days IS NULL OR fridge_days BETWEEN 0 AND 365),
  cooked_yield  numeric(4,2) CHECK (cooked_yield IS NULL OR cooked_yield > 0),
  measures      jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(measures) = 'object'),
  piece_name    text,
  piece_is_name boolean NOT NULL DEFAULT false,
  data_version  text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE food.food_item IS 'Per-100 g figures (raw, edible) for the foods recipe lines are sized with. IFCT 2017 first; source + source_ref on every row. Seed of the food database.';

ALTER TABLE food.food_item ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON food.food_item FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON food.food_item TO service_role;

INSERT INTO food.food_item (key, name, kcal_100g, protein_100g, carbs_100g, fat_100g, fibre_100g, source, source_ref, fridge_days, cooked_yield, measures, piece_name, piece_is_name, data_version) VALUES
${foodRows}
ON CONFLICT (key) DO UPDATE SET
  name = EXCLUDED.name, kcal_100g = EXCLUDED.kcal_100g, protein_100g = EXCLUDED.protein_100g,
  carbs_100g = EXCLUDED.carbs_100g, fat_100g = EXCLUDED.fat_100g, fibre_100g = EXCLUDED.fibre_100g,
  source = EXCLUDED.source, source_ref = EXCLUDED.source_ref, fridge_days = EXCLUDED.fridge_days,
  cooked_yield = EXCLUDED.cooked_yield, measures = EXCLUDED.measures, piece_name = EXCLUDED.piece_name,
  piece_is_name = EXCLUDED.piece_is_name, data_version = EXCLUDED.data_version;
`;

const lineRows = [];
const dishRows = [];
const stepRows = [];
for (const dish of DISHES) {
  const r = RECIPES[dish.key];
  if (!r) throw new Error(`${dish.key}: no recipe`);
  r.g.forEach(([food, grams], i) => lineRows.push(`  (${q(dish.key)}, ${i}, ${q(food)}, ${n(grams)})`));
  dishRows.push(`  (${q(dish.key)}, ${n(r.served ?? null)}, ${n(r.keeps ?? 0)}, ${r.batch ? "true" : "false"})`);
  (r.steps ?? []).forEach(([title, body, minutes = null, timer = null], i) => {
    stepRows.push(`  (${q(dish.key)}, ${i + 1}, ${q(title)}, ${q(body)}, ${n(minutes)}, ${n(timer)})`);
  });
}

const recipes = `-- ============================================================================
-- 00088_recipe_quantities — every dish gets amounts and a method (exact macros, P1).
-- GENERATED by web/scripts/buildRecipes.mjs from web/src/lib/food/recipes/*.js.
--
-- 00068 left quantities out on purpose: the plan's amounts were the planner's
-- shares of the basket. Exact macros need grams, so each line now names the
-- food it is (food.food_item) and how many grams ONE adult serving takes. The
-- engine scales servings to a person's numbers and rounds to kitchen measures;
-- these are the editorial base, not a prescription. Lines are matched in the
-- dish's own line order (the order dishData.js carries), never by a guessed
-- position. Steps are templates: {n} names line n (0-based) and {water:g}
-- names water, filled in at the servings being cooked.
-- ============================================================================

ALTER TABLE food.recipe_line
  ADD COLUMN IF NOT EXISTS food_key text REFERENCES food.food_item(key),
  ADD COLUMN IF NOT EXISTS grams_per_serving numeric(7,2) CHECK (grams_per_serving IS NULL OR grams_per_serving > 0);

ALTER TABLE food.dish
  ADD COLUMN IF NOT EXISTS served_grams smallint CHECK (served_grams IS NULL OR served_grams > 0),
  ADD COLUMN IF NOT EXISTS keeps_days smallint NOT NULL DEFAULT 0 CHECK (keeps_days BETWEEN 0 AND 7),
  ADD COLUMN IF NOT EXISTS batchable boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS recipe_version text;

CREATE TABLE IF NOT EXISTS food.recipe_step (
  dish_key      text NOT NULL REFERENCES food.dish(key) ON DELETE CASCADE,
  position      smallint NOT NULL CHECK (position > 0),
  title         text NOT NULL CHECK (btrim(title) <> ''),
  body          text NOT NULL CHECK (btrim(body) <> ''),
  minutes       smallint CHECK (minutes IS NULL OR minutes BETWEEN 0 AND 600),
  timer_seconds integer CHECK (timer_seconds IS NULL OR timer_seconds BETWEEN 1 AND 36000),
  PRIMARY KEY (dish_key, position)
);

COMMENT ON TABLE food.recipe_line IS 'What a dish is made of, where each part comes from, which food it is and the grams one adult serving takes (00088). The engine scales servings; these are the editorial base.';
COMMENT ON TABLE food.recipe_step IS 'A dish''s method. body is a template: {n} names recipe line n in line order (0-based), {water:g} names water; filled in at the servings being cooked.';

ALTER TABLE food.recipe_step ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON food.recipe_step FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON food.recipe_step TO service_role;

WITH ranked AS (
  SELECT dish_key, position, (row_number() OVER (PARTITION BY dish_key ORDER BY position) - 1)::int AS idx
  FROM food.recipe_line
), amounts (dish_key, idx, food_key, grams) AS (VALUES
${lineRows.join(",\n")}
)
UPDATE food.recipe_line r
SET food_key = a.food_key, grams_per_serving = a.grams
FROM ranked k JOIN amounts a ON a.dish_key = k.dish_key AND a.idx = k.idx
WHERE r.dish_key = k.dish_key AND r.position = k.position;

UPDATE food.dish d
SET served_grams = v.served, keeps_days = v.keeps, batchable = v.batch, recipe_version = ${q(RECIPE_VERSION)}
FROM (VALUES
${dishRows.join(",\n")}
) AS v (key, served, keeps, batch)
WHERE d.key = v.key;

INSERT INTO food.recipe_step (dish_key, position, title, body, minutes, timer_seconds) VALUES
${stepRows.join(",\n")}
ON CONFLICT (dish_key, position) DO UPDATE SET
  title = EXCLUDED.title, body = EXCLUDED.body, minutes = EXCLUDED.minutes, timer_seconds = EXCLUDED.timer_seconds;

-- Every line of every dish must now have a food and grams; anything else means
-- the database's dishes drifted from dishData.js and the file must be rebuilt.
DO $$
DECLARE missing int;
BEGIN
  SELECT count(*) INTO missing FROM food.recipe_line WHERE food_key IS NULL OR grams_per_serving IS NULL;
  IF missing > 0 THEN
    RAISE EXCEPTION '00088: % recipe lines have no amount; dishData.js is out of step with food.recipe_line', missing;
  END IF;
END $$;
`;

const files = [["00087_food_items.sql", foods], ["00088_recipe_quantities.sql", recipes]];
let stale = false;
for (const [name, body] of files) {
  const file = path.join(DIR, name);
  if (CHECK) {
    const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n") : "";
    if (current !== body) { console.error(`${name} is stale. Run scripts/buildRecipes.mjs.`); stale = true; }
  } else {
    fs.writeFileSync(file, body);
    console.log(`Wrote ${name}`);
  }
}
console.log(`${FOODS.length} foods (${FOOD_VERSION}), ${lineRows.length} lines, ${stepRows.length} steps (${RECIPE_VERSION})`);
if (stale) process.exit(1);
